/* ACSS Programmatic Dividers */
/* Available Override Tokens
--divider-size
--divider-inline-size
--divider-style
--divider-color
*/

/* Remove gap from parent */
.faq-list-charlie {
  --divider-gap: calc(var(--container-gap) / 1.5);
	row-gap: 0 !important;
  padding: 0;
  margin: 0;
  list-style-type: none;
}

/* Children are required to be relative and show overflow. They also need bottom margin to act as a gap. */
.faq-list-charlie > *:not(:last-child) {
		position: relative;
	overflow: visible;
	margin-block-end: calc(var(--divider-gap) * 2);
}

/* Divider */
