		content: '';
	display: block;
	position: absolute;
	inset-inline-start: 0;
	inset-block-end: calc(var(--divider-gap) * -1 - var(--divider-size));
	inline-size: var(--divider-inline-size);
	border-block-end: var(--divider);
}

